INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛で、味方をプリンで強化する幽霊聖少女。\n物理攻撃力と物理クリティカルアップのプリンパワーの\nフィールドで自分のスキルも強化し、猛攻を繰り出す。", 0, "2025/12/31 11:59:59", 0, "2025/12/21 12:00:00", 1, 2.17, "ミヤコ（クリスマス）", 119901, 1, 119901, "みやこ", 119901, 302, 0, 119901, 3, 14, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】前衛で猛攻から味方を守護する闇のお姉ちゃん。\nバトル開始時の行動不能無効スキルで周囲の味方を守り、\n範囲を束縛するスキルで敵を牽制し、戦況を一変する。", 0, "2026/03/31 11:59:59", 0, "2026/03/16 10:00:00", 5, 2.375, "シズル（ノワール）", 120001, 5, 120001, "しずる", 120001, 190, 0, 120001, 3, 6, 0, 1, 0, 450, 1);
