INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 1, "", 0, "2030/12/31 15:00:00", 0, "2015/04/01 15:00:00", 1, 0, "プレシア", 131501, 1, 0, "ぷれしあ", 0, 0, 0, 131501, 3, 0, 0, 0, 0, 0, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛で、夏の陽光のもと研鑽する妹系大和撫子。\n防御力アップに加えバリアやＨＰ回復で味方の守りを固め\nＴＰ回復や攻撃力ダウンをも巧みに操り、場を支配する。", 0, "2026/07/31 11:59:59", 0, "2026/07/15 12:00:00", 4, 1.92, "リリ（サマー）", 131601, 4, 131601, "りり", 131601, 399, 0, 131601, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で、黄昏の水面に舞い降りる水着姿の妖精。\n行動速度アップやＴＰ支援をはじめとした多数のサポート\nを施しつつ、ＵＢの攻防弱体化で清爽に勝利へと導く。", 0, "2026/08/31 11:59:59", 0, "2026/08/26 12:00:00", 53, 1.92, "アメス（サマー）", 131701, 44, 131701, "あめす", 131701, 743, 0, 131701, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で夏の清涼に翼を休める水着姿の龍の首領。\n攻防弱体化に加え、ステータスダウン付与のたび増加する\n【日食】の数に応じたダメージで、抗う全てを灰に帰す。", 0, "2030/12/31 15:00:00", 0, "2024/08/15 15:00:00", 21, 2.09, "ホマレ（サマー）", 131801, 7, 131801, "ほまれ", 131801, 709, 0, 131801, 3, 0, 0, 2, 0, 450, 0);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 1, "【魔法】後衛で、パックと共に戦う真夏のハーフエルフ。\n氷壁を生成するスキルや、強力なダメージと速度ダウンを\n付与するユニオンバーストで、敵の侵攻を食い止める。", 0, "2030/12/31 15:00:00", 1, "2024/08/31 12:00:00", 23, 2.09, "エミリア（サマー）", 131901, 7, 131901, "えみりあ", 131901, 725, 0, 131901, 1, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で未知の世界との邂逅に胸躍る強欲の魔女。\n鮮烈な攻撃魔法をはじめ、味方への攻撃支援、敵の弱体化\nから自己蘇生まで、あらゆる魔法を振るい、欲を満たす。", 0, "2025/10/24 11:59:59", 1, "2025/10/10 12:00:00", 21, 2.09, "エキドナ（サマー）", 132001, 7, 132001, "えきどな", 132001, 775, 0, 132001, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】前衛で夏の日差しの中、余暇を楽しむ双子の妹。\nＵＢで鬼族の力を解放すると攻防両面に加えＨＰ吸収が\n上昇し、目に映る全てを【狂騒】のままに叩き伏せる。", 0, "2025/10/24 11:59:59", 1, "2025/10/10 12:00:00", 24, 2.09, "レム（サマー）", 132101, 13, 132101, "れむ", 132101, 146, 0, 132101, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で、希望を錬成するアルケミストアイドル。\n【錬金素材】から【パフューム】を創り、ダメージに加え\nＴＰ回復や攻撃支援能力を向上させて勝利の香りを運ぶ。", 0, "2026/10/31 11:59:59", 0, "2026/10/15 12:00:00", 7, 1.84, "ノゾミ（アルケミスト）", 132201, 7, 132201, "のぞみ", 132201, 721, 0, 132201, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で、底知れぬ叡智を秘めた天才錬金術師。\n高い方の防御力でダメージを受ける調和状態を付与し、\n２回まで性能が上昇していくＵＢで、妄想を爆発させる。", 0, "2026/05/22 11:59:59", 0, "2026/05/11 12:00:00", 7, 2.09, "ルイズマリー", 132301, 7, 132301, "るいずまりー", 132301, 754, 0, 132301, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛で、大きな体で無邪気に遊び回る天才剣士。\n戦いの中で【剣圧】を溜め、その後のスキルやＵＢで物防\n一定無視のダメージを連発し、才気煥発の活躍を見せる。", 0, "2030/12/31 15:00:00", 0, "2025/06/20 12:00:00", 0, 2.09, "イロハ", 132401, 5, 132401, "いろは", 132401, 501, 0, 132401, 3, 0, 0, 1, 0, 450, 0);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で、小柄で大人対応な錬金堂の省エネ店主。\n強力な弱体効果を与えながら、デバフ付与のたび増加する\n【虚脱】が80溜まると本気を出し定時厳守で戦い抜く。", 0, "2030/12/31 15:00:00", 0, "2025/05/15 15:00:00", 23, 2.09, "ソノ", 132501, 7, 132501, "その", 132501, 636, 0, 132501, 3, 0, 0, 2, 0, 450, 0);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で、雪白の肌を黒衣に包んだ甘美なる姫君。\n味方のＨＰを代償に強力なバリアを展開しつつ、バリアを\n起点とした高出力の二連撃で、聖夜の大樹に灯を点す。", 0, "2025/12/15 14:59:59", 0, "2025/11/30 12:00:00", 0, 2.09, "ライラエル（クリスマス）", 132801, 7, 132801, "らいらえる", 132801, 750, 0, 132801, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で、心地良い眠りの中に訪れる聖夜の悪魔。\n最も魔法攻撃力が高い味方に【悪魔の口づけ】を付与し、\n攻撃支援とＴＰ回復による付きっきりの手ほどきをする。", 0, "2030/12/31 15:00:00", 0, "2024/12/09 12:00:00", 46, 2.09, "イオ（クリスマス）", 132901, 5, 132901, "いお", 132901, 748, 0, 132901, 3, 0, 0, 2, 0, 450, 0);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】前衛で、宙を舞うように戦う幽霊の守護騎士。\nＵＢで味方の攻撃と速度支援を行い、【レイスボディ】で\n敵の目を逃れ、不意を突く一撃で永遠の眠りにつかせる。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 2.09, "グレイス", 133001, 0, 133001, "ぐれいす", 133001, 234, 0, 133001, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】前衛で、儚くも凛と咲くジオ・ニヴルヘルの姫。\n継続ダメージ効果を鈍化させる環境効果【忌火】で盾に、\n絶怠霊度の継続割合攻撃で矛となり、静寂の冥府を護る。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 1.75, "ヴァイオレット", 133101, 0, 133101, "うぁいおれっと", 133101, 154, 0, 133101, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 1, "【物理】前衛で、元日も元気にはしゃぎまわる軍人少女。\n与ダメージに応じて追加効果が強化されるＵＢと、発動ご\nとに成長する自己強化スキルで秩序を乱す者の目を回す。", 0, "2030/12/31 15:00:00", 0, "2024/12/31 12:00:00", 22, 2.09, "モニカ（ニューイヤー）", 133201, 4, 133201, "もにか", 133201, 296, 0, 133201, 1, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で、傍らで心を重ねる振袖姿の救護院の主。\n味方へのＴＰ回復の支援をしつつ、味方がＵＢを発動する\nたびダメージが上がるスキルで、共に困難を乗り越える。", 0, "2026/01/15 11:59:59", 0, "2026/01/03 12:00:00", 22, 2.09, "サレン（ニューイヤー）", 133501, 4, 133501, "されん", 133501, 718, 0, 133501, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛で眷属と力を合わせて戦う誇り高き蛇乙女。\n【魔眼】の数に応じて効果量が上がるスキルのダメージと\n弱体化で範囲内の敵を追い詰め、鋭い瞳で石へと変える。", 0, "2026/01/15 11:59:59", 0, "2026/01/03 12:00:00", 0, 2.09, "メドゥーサ", 133601, 0, 133601, "めどぅーさ", 133601, 445, 0, 133601, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で、始原の冠装を使いこなす『迷宮女王』。\n水属性の味方のＴＰ上昇を増加する領域を作り、連射攻撃\nで敵の防御を撃ち抜くことで七冠の力を敵に知らしめる。", 0, "2026/02/15 11:59:59", 0, "2026/02/09 12:00:00", 0, 2.09, "ラビリスタ（アルファ）", 133701, 8, 133701, "らびりすた", 133701, 717, 0, 133701, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛から、始原の姿で戦況を操る『変貌大妃』。\n召喚したグレゴールから攻撃支援とＴＰ回復を受け、互い\nの魔力を合わせた連携攻撃で、幽玄なる玉座に君臨する。", 0, "2026/02/15 11:59:59", 0, "2026/02/09 12:00:00", 0, 2.09, "ネネカ（アルファ）", 133801, 7, 133801, "ねねか", 133801, 759, 0, 133801, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】前衛で、始原の冠装の力を振るう『誓約女君』。\n10行動目に攻撃力を大幅アップし、スキルに追撃を発生\nさせる【虚数】を得て隔絶した力で楯突く敵を抹消する。", 0, "2026/02/15 11:59:59", 0, "2026/02/09 12:00:00", 0, 2.09, "クリスティーナ（アルファ）", 133901, 6, 133901, "くりすてぃーな", 133901, 228, 0, 133901, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で、アストルムの冒険へと導くガイド妖精。\nバフとバリアで味方を護りバリアを起点とする攻撃支援、\n風属性の味方への行動速度とＴＰの支援で仲間を支える。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 2.09, "フィオ", 134001, 0, 134001, "ふぃお", 134001, 746, 0, 134001, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "", 0, "2030/12/31 15:00:00", 0, "2015/04/01 15:00:00", 1, 0, "フブキ", 134101, 5, 0, "ふぶき", 0, 0, 0, 134101, 3, 0, 0, 0, 0, 0, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "", 0, "2030/12/31 15:00:00", 0, "2015/04/01 15:00:00", 1, 0, "ライラエル（クリスマス）", 134201, 7, 0, "らいらえる", 0, 0, 0, 134201, 3, 0, 0, 0, 0, 0, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で儀装束を纏い精霊と心を通わせる唱喚士。\n敵の数に応じてダメージ量が変化する範囲攻撃や、魔法\n無効バリアなどの支援スキルで想いを詩に乗せ響かせる。", 0, "2026/03/16 9:59:59", 0, "2026/03/03 12:00:00", 0, 2.09, "ランファ（儀装束）", 134301, 7, 134301, "らんふぁ", 134301, 778, 0, 134301, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で儀装束を纏い歌を紡ぎ伝えていく唱喚士。\n自分と最も近くの味方へ強力なバフとＴＰ回復を行うこと\nで攻撃を支援し、共に心を通わせ美しき旋律を奏でる。", 0, "2030/12/31 15:00:00", 0, "2025/03/15 15:00:00", 21, 2.09, "チカ（儀装束）", 134401, 7, 134401, "ちか", 134401, 773, 0, 134401, 3, 0, 0, 2, 0, 450, 0);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で超速飛行からの大火力を叩き込むロボ娘。\n上空から速度バフで味方全体を支援しつつ、自分のバリア\nを解除して力へと変え、世界の命運を背負い飛翔する！", 0, "2026/04/30 11:59:59", 0, "2026/04/15 12:00:00", 0, 2.09, "クローチェ（エアリアル）", 134501, 0, 134501, "くろーちぇ", 134501, 719, 0, 134501, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛で巨大ロボを駆り戦うぼっちのパイロット。\n敵の弱体化や、味方へバリアを展開するスキルを持ち、\n鋼鉄の乙女から放つ光線はいかに堅固な守りも打ち破る。", 0, "2026/04/30 11:59:59", 0, "2026/04/15 12:00:00", 35, 2.09, "アオイ（パイロット）", 134601, 35, 134601, "あおい", 134601, 526, 0, 134601, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛で、華麗に舞い踊る五色絢爛な煉華の鳳凰。\n攻撃力バフやバリア展開などの攻防支援と、多彩で豊富な\nＨＰ・ＴＰ供給を両立し、浄化の力で皆に安寧を授ける。", 0, "2026/04/30 11:59:59", 0, "2026/04/15 12:00:00", 7, 2.09, "ホウオウ", 134701, 7, 134701, "ほうおう", 134701, 490, 0, 134701, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛から、新たな素材で紡ぐワイルドテーラー。\n最も物攻が高い他の味方へ重複速度アップやＴＰ・攻撃支\n援を仕立て、全体へのＨＰ回復と併せ攻守を両立させる。", 0, "2026/06/22 11:59:59", 0, "2026/06/10 12:00:00", 1, 1.84, "ツムギ（ジオ・ゲヘナ）", 134801, 1, 134801, "つむぎ", 134801, 485, 0, 134801, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】前衛で、おエレガントな高笑いを轟かすド令嬢。\nＵＢや敵からの攻撃で【お堪忍袋】が尽きると逆上し、強\n化されたスキルと行動パターンで華麗におリベンジする。", 0, "2026/06/22 11:59:59", 0, "2026/06/10 12:00:00", 0, 2.09, "カノン", 134901, 2, 134901, "かのん", 134901, 196, 0, 134901, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で、永く夢見た本物の夏に咲き綻ぶ黒薔薇。\n【いばらの冠】の呪縛は再臨により解き放たれ、調和状態\nや攻防支援、回復効果を施し、月下の浜辺に静かに佇む。", 0, "2026/07/15 11:59:59", 0, "2026/07/03 12:00:00", 21, 2.09, "エリス（サマー）", 135001, 7, 135001, "えりす", 135001, 785, 0, 135001, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】前衛で盛夏の白波を華麗に乗りこなす氷竜少女。\n敵全体を挑発し、被弾で溜まる【ぐずぐず】をＵＢで発散\nすることで周囲に攻撃支援と天真爛漫な笑顔を振りまく。", 0, "2026/07/15 11:59:59", 0, "2026/07/03 12:00:00", 4, 2.09, "シェフィ（サマー）", 135101, 4, 135101, "しぇふぃ", 135101, 143, 0, 135101, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】中衛で夏の食を満喫し、ぷかぷか漂う天然少女。\nＴＰ・攻撃支援やバリアは味方の数で効果量が変化し、物\n理と魔法攻撃力合算のダメージで夏の思い出を心に刻む。", 0, "2026/07/15 11:59:59", 0, "2026/07/03 12:00:00", 7, 2.09, "プレシア（サマー）", 135201, 7, 135201, "ぷれしあ", 135201, 548, 0, 135201, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛で友情の芽を育む、真夏の『普通』の少女。\n【プルメリアのお守り】で強力な一撃から先頭を守り、味\n方の数で効果量が変化するスキルを鮮やかに命中させる。", 0, "2026/08/15 11:59:59", 0, "2026/07/31 12:00:00", 54, 2.09, "クリア（サマー）", 135301, 54, 135301, "くりあ", 135301, 413, 0, 135301, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】中衛で砂浜の木陰に微睡むアルラウネの妖魔人。\n行動速度アップや初回発動時に回復量が増加するＴＰ回復\nを起点に支援し、穏やかな木漏れ日と共にゆらゆら憩う。", 0, "2026/08/15 11:59:59", 0, "2026/07/31 12:00:00", 52, 2.09, "アネモネ（サマー）", 135401, 2, 135401, "あねもね", 135401, 553, 0, 135401, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】前衛で、世界を守り笑顔を咲かせる情熱の豪炎。\n前方の敵全てを対象とする連撃の強化通常攻撃や、天楼覇\n断剣から放たれる極大ダメージの一閃で未来を切り拓く。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 2.09, "アイラ", 135501, 1, 135501, "あいら", 135501, 213, 0, 135501, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】前衛から、風裂く刃で世界を護る孤高の剣豪。\n卓越した剣技で敵の攻撃を捌いて反撃し、初回ＵＢで生成\nする分身と共に疾風迅雷の攻めで、未来へと駆け抜ける。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 0.4, "シナツ", 135601, 4, 135601, "しなつ", 135601, 198, 0, 135601, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】前衛で、二人きりの月下の空旅にときめく黒猫。\n物防弱体の他、ダメージ100ヒット後には華麗なステップ\nの追撃とＴＰ回復量増加で、砂漠の夜空に花を咲かせる。", 0, "2030/12/31 15:00:00", 0, "2025/09/16 15:00:00", 0, 1.84, "ヒヨリ（サラサリア）", 135701, 1, 135701, "ひより", 135701, 291, 0, 135701, 3, 0, 0, 1, 0, 450, 0);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛から、雪魄氷姿の三味を弾じる初心な雪女。\n多様なデバフ効果で敵を弱体化させ、最も魔防の低い敵の\n状態に応じて発生する追加効果で、冥府を真白に染める。", 0, "2026/10/15 11:59:59", 0, "2026/09/30 12:00:00", 0, 2.09, "ユキノ", 135801, 7, 135801, "ゆきの", 135801, 830, 0, 135801, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】前衛で、華奢な体躯に厚い仁義を宿す鬼のお嬢。\n攻防自己強化や行動不能無効化で豪胆に立ち続け、自分が\n呪詛状態の時に振るう追加攻撃で、怪力無双の力を示す。", 0, "2026/10/15 11:59:59", 0, "2026/09/30 12:00:00", 0, 1.84, "サツキ", 135901, 3, 135901, "さつき", 135901, 219, 0, 135901, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】後衛で、喪われた光を求めてもがく元『六凶』。\n敵のＵＢを遅延する【遮絶の操糸】や、味方単体のＵＢを\n連続発動可能にする【賦活の糸】を戦場に張り巡らせる。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 2.09, "アラクネ", 136001, 11, 136001, "あらくね", 136001, 732, 0, 136001, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛で不運に抗い歌い続けるゾンビィアイドル。\n一度倒れても立ち上がり、ＴＰを糧に強化されるスキルの\nダメージと味方の支援で、サガの心をアストルムに刻む。", 0, "2025/11/03 11:59:59", 1, "2025/10/24 12:00:00", 0, 1.74, "サクラ", 136101, 0, 136101, "さくら", 136101, 432, 0, 136101, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】前衛でダメダメでも逃げず戦うアルミラージ娘。\n最も近くの味方に強化や行動不能無効の付与、回復を行い\n敵の注意をそらすことで、過酷な世界を生き延びる。", 0, "2030/12/31 15:00:00", 0, "2025/11/14 15:00:00", 3, 2.09, "ナーナ", 136201, 3, 136201, "なーな", 136201, 198, 0, 136201, 3, 0, 0, 1, 0, 450, 0);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で、シゲキ的な聖夜に鼓動高鳴る溌溂少女★\n【イルミネーションバレット】を消費して味方を支援し、\n40消費後は追加の範囲攻撃やバフでキュン★を届ける。", 0, "2026/07/15 11:59:59", 0, "2026/07/03 12:00:00", 54, 2.09, "ミソラ（クリスマス）", 136301, 35, 136301, "みそら", 136301, 655, 0, 136301, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】中衛で、騎士の隣に一歩踏み出す聖夜の魔法士。\n敵の注目を集めながら攻防支援を行い【聖夜の愛慕】が\n高まると、ＴＰ支援やダメージカットで優しく包み込む。", 0, "2026/07/15 11:59:59", 0, "2026/07/03 12:00:00", 21, 1.84, "ユイ（クリスマス）", 136401, 7, 136401, "ゆい", 136401, 382, 0, 136401, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】前衛で、凛然と立ちはだかる新年のお姉ちゃん。\n挑発と行動不能無効で攻撃を鮮やかに捌き、状況に応じて\n物理・魔法を自在に操り、弟くんへの愛を見せつける。", 0, "2026/08/23 11:59:59", 0, "2026/08/15 12:00:00", 0, 2.09, "シズル（ニューイヤー）", 136501, 5, 136501, "しずる", 136501, 151, 0, 136501, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "", 0, "2030/12/31 15:00:00", 0, "2015/04/01 15:00:00", 1, 0, "メドゥーサ", 136601, 1, 0, "めどぅーさ", 0, 0, 0, 136601, 1, 0, 0, 0, 0, 0, 0);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "", 0, "2030/12/31 15:00:00", 0, "2015/04/01 15:00:00", 1, 0, "ラビリスタ（アルファ）", 136701, 8, 0, "らびりすた", 0, 0, 0, 136701, 3, 0, 0, 0, 0, 0, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "", 0, "2030/12/31 15:00:00", 0, "2015/04/01 15:00:00", 1, 0, "ランファ（儀装束）", 136801, 7, 0, "らんふぁ", 0, 0, 0, 136801, 3, 0, 0, 0, 0, 0, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛でうねる、珍味な触手の小姓見習いタコ娘。\nＴＰ回復、継続ＨＰ回復、バリアで味方をもてなし、多様\nな弱体効果を与える自慢の墨で、敵を真っ黒に染める。", 0, "2030/12/31 15:00:00", 0, "2026/05/22 12:00:00", 0, 2.09, "ルルィ", 136901, 3, 136901, "るるぃ", 136901, 409, 0, 136901, 3, 0, 0, 1, 0, 450, 0);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】中衛で陽光の下、煌く水面を共に駆けるシノビ。\n【水遁の印】を自らの攻撃力へと変え、束縛フィールドと\n水遁の術で最も遠い敵とその周囲に速やかな天誅を下す。", 0, "2030/12/31 15:00:00", 0, "2025/08/15 15:00:00", 47, 2.09, "ニノン（サマー）", 137101, 8, 137101, "にのん", 137101, 566, 0, 137101, 3, 0, 0, 2, 0, 450, 0);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "", 0, "2030/12/31 15:00:00", 0, "2015/04/01 15:00:00", 2, 0, "ラビリスタ", 137201, 2, 0, "らびりすた", 0, 0, 0, 137201, 3, 0, 0, 0, 0, 0, 0);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "", 0, "2030/12/31 15:00:00", 0, "2015/04/01 15:00:00", 1, 0, "カノン", 137301, 2, 0, "かのん", 0, 0, 0, 137301, 3, 0, 0, 0, 0, 0, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で、聖なる光に包まれ微笑み祈るシスター。\n攻防デバフを操り【真実の導き】が集まると最大３キャラ\nへの攻撃が最も魔防の低い敵を追及し、真理を照らす。", 0, "2026/11/16 11:59:59", 0, "2026/10/31 12:00:00", 21, 2.09, "カスミ（シスター）", 137401, 7, 137401, "かすみ", 137401, 688, 0, 137401, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "", 0, "2030/12/31 15:00:00", 0, "2015/04/01 15:00:00", 1, 0, "アイラ", 137501, 1, 0, "あいら", 0, 0, 0, 137501, 3, 0, 0, 0, 0, 0, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で、主さまを想い“進化”した嚮導の巫女。\n極大ダメージのＵＢで敵を穿ち、【進化超越】の権能によ\nって、味方のバフやダメージを、限界を超え成長させる。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 2.09, "コッコロ（嚮導幼君）", 137601, 7, 137601, "こっころ", 137601, 733, 0, 137601, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "", 0, "2030/12/31 15:00:00", 0, "2015/04/01 15:00:00", 1, 0, "ユキノ", 137801, 7, 0, "ゆきの", 0, 0, 0, 137801, 3, 0, 0, 0, 0, 0, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で絵馬に込めた想いを胸に抱く晴れ着の妹。\nクリティカル時に威力が上がる矢で敵を撃ち抜き、味方\n全体への攻撃支援や継続ＴＰ回復で厄を払い福を届ける。", 0, "2026/08/23 11:59:59", 0, "2026/08/15 12:00:00", 8, 2.09, "リノ（ニューイヤー）", 137901, 8, 137901, "りの", 137901, 684, 0, 137901, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】前衛から慈愛の心で冥府を包む彼岸の屍姫。\nＵＢは敵全体を呑み込む割合ダメージを与え、【冥海の加\n護】を消費して味方の攻防ダウン効果までも禊ぎ清める。", 0, "2026/09/22 11:59:59", 0, "2026/09/10 12:00:00", 0, 2.09, "ヴァイオレット（イサナミ）", 138001, 0, 138001, "うぁいおれっと", 138001, 154, 0, 138001, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で、民とハーモニーを奏でる天使の姫君。\nステータスアップ効果を受け【エクスマキナ】が溜まると\n行動パターンが変化し、絶え間ない弓撃で神威を示す。", 0, "2026/09/22 11:59:59", 0, "2026/09/10 12:00:00", 0, 2.09, "ライラエル（パルフェクト）", 138101, 0, 138101, "らいらえる", 138101, 729, 0, 138101, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛から怯懦を退け、万魔を率する煉獄の鉄媛。\n千変万化の躰は行動速度アップを始めとする多彩な支援と\nすべての敵の弱体を両立し、天地万象を掌の内に収める。", 0, "2026/09/22 11:59:59", 0, "2026/09/10 12:00:00", 0, 2.09, "ネフィ＝ネラ（鬼面仏心）", 138201, 0, 138201, "ねふぃーねら", 138201, 502, 0, 138201, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】前衛で女神の血脈と矜持を揮う全力全開の王女。\n物理攻撃力の高い味方を【裁定の盾】で庇い、自身は圧倒\n的な防御とＨＰ回復で前線に立ち幸せな食卓を守り抜く。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 2.09, "ペコリーヌ（アストライア）", 138301, 0, 138301, "ぺこりーぬ", 138301, 142, 0, 138301, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "", 0, "2030/12/31 15:00:00", 0, "2015/04/01 15:00:00", 1, 0, "サクラ", 138601, 1, 0, "さくら", 0, 0, 0, 138601, 3, 0, 0, 0, 0, 0, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛で恥じらいながらも激戦に飛び込む桃闘者。\n味方を【スパイクシール】で守りつつ、自身は物理防御力\nダウンで敵を切り崩し、鍛え上げた桃尻を存分に振るう。", 0, "2026/10/15 11:59:59", 0, "2026/09/30 12:00:00", 55, 2.09, "ワカナ（ウィンター）", 138701, 7, 138701, "わかな", 138701, 539, 0, 138701, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛で、過酷なお尻の世界を生き抜く桃闘者。\n攻防ダウンを併せ持つＵＢを矢継ぎ早に放ち、ステータス\nダウン効果で付与する【魅惑の矢】で敵を骨抜きにする。", 0, "2026/10/15 11:59:59", 0, "2026/09/30 12:00:00", 8, 2.09, "シオリ（ウィンター）", 138801, 8, 138801, "しおり", 138801, 571, 0, 138801, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛で、妖しく跳ねるバニーの幽霊守護騎士。\n物理攻撃力を代償に物理クリダメを極大アップし、【ブラ\nックうさ耳】で油断した敵の虚を突き、御首を頂戴する。", 0, "2026/11/16 11:59:59", 0, "2026/10/31 12:00:00", 0, 2.09, "グレイス（バニー）", 138901, 4, 138901, "ぐれいす", 138901, 429, 0, 138901, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で、破滅の運命にあらがうお嬢様？優等生。\n【呪いの鎖】の溢れる魔力で魔防デバフやＴＰ、速度支援\nを行うが、限界を迎えると永久的狂気に陥ってしまう。", 0, "2026/11/16 11:59:59", 0, "2026/10/31 12:00:00", 7, 2.09, "キョウカ（ゴシック）", 139001, 7, 139001, "きょうか", 139001, 816, 0, 139001, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で、天の星を瞳に映し、仲間と進む黒猫娘。\n敵全体を激烈に弱体化させながら、【千里真眼】状態時に\n未来を視通す能力で仲間をあらゆる脅威から遠ざける。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 2.09, "キャル（覇瞳天星）", 139101, 0, 139101, "きゃる", 139101, 770, 0, 139101, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 1, "【魔法】中衛で臨機応変に作戦を指揮する戦車道の乙女。\n召喚したボコが敵の攻撃を引き付けている間に、周囲の\n味方の攻撃、回復支援によって、全員での勝利を目指す。", 0, "2030/12/31 15:00:00", 1, "2026/04/30 12:00:00", 0, 2.09, "ミホ（ガルパン）", 139201, 0, 139201, "みほ", 139201, 486, 0, 139201, 1, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】後衛から必中の一射で敵を貫く西住流の継承者。\n【榴弾】を装填した状態のＵＢは、防御力を無視する火傷\nフィールドを発生させ、圧倒的な戦力差で敵を蹂躙する。", 0, "2026/05/22 11:59:59", 1, "2026/04/30 12:00:00", 0, 2.09, "マホ（ガルパン）", 139301, 0, 139301, "まほ", 139301, 700, 0, 139301, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛から迅速な強襲で戦局を切り拓く双剣使い。\nバトル開始直後からＴＰを消費する強力なスキルの連撃で\n敵の防御力を一気に下げ、敵陣深くまで浸透突破する。", 0, "2026/05/22 11:59:59", 1, "2026/05/11 12:00:00", 0, 1.04, "エリカ（ガルパン）", 139401, 0, 139401, "えりか", 139401, 322, 0, 139401, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】中衛で、寄る辺無き魂を繋ぎ導く清廉の戦乙女。\nダメージと共に敵の魔防を削ぎ、継続ダメージを与える聖\n浄の光が戦乙女の聖槍を降り注がせ、敵を清め祓う。", 0, "2026/06/10 11:59:59", 0, "2026/05/31 12:00:00", 0, 2.09, "リリ（ヴァルキュリア）", 139501, 0, 139501, "りり", 139501, 453, 0, 139501, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】前衛で、奇跡により魂の疵を癒す浄罪の戦乙女。\n味方を物理攻撃から堅牢に守り、継続ダメージを与える聖\n浄の光を敵に浴びせ、戦乙女の聖槍による天罰を下す。", 0, "2026/06/30 11:59:59", 0, "2026/06/22 12:00:00", 0, 2.09, "クリア（ヴァルキュリア）", 139601, 2, 139601, "くりあ", 139601, 150, 0, 139601, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】中衛で、正義の光で邪な魂を祓う勧善の戦乙女。\n多彩な支援効果で味方を支え、継続ダメージを与える聖浄\nの光が戦乙女の聖槍を喚び寄せ、悪をこらしめる。", 0, "2026/06/22 11:59:59", 0, "2026/06/10 12:00:00", 0, 2.09, "プレシア（ヴァルキュリア）", 139701, 0, 139701, "ぷれしあ", 139701, 500, 0, 139701, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛で兄妹の絆と不撓の心で覚醒した氷竜少女。\n個も群も薙ぎ払うＵＢと、【氷竜超克】状態時に発生する\n追撃状態で敵を咬断し、大切な人と歩む未来を切り拓く。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 2.09, "シェフィ（ヴァードラッヘ）", 139801, 0, 139801, "しぇふぃ", 139801, 386, 0, 139801, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で、大人の階段を上りたい水着の錬金術師。\n発動回数で性能が上昇するＵＢとスキルで、調和状態の\n付与と攻防たゆまぬ支援を行い、ひと夏の思い出を創る。", 0, "2026/07/15 11:59:59", 0, "2026/07/03 12:00:00", 55, 2.09, "ルイズマリー（サマー）", 139901, 55, 139901, "るいずまりー", 139901, 757, 0, 139901, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で、リゾート建設に奔走する水着の女商人。\n初回発動時に強力な攻撃支援と一定時間魔攻・物防・魔防\nダウンを無効化するスキルで、豪奢に味方を駆り立てる。", 0, "2026/07/31 11:59:59", 0, "2026/07/15 12:00:00", 54, 2.09, "クレジッタ（サマー）", 140001, 54, 140001, "くれじった", 140001, 730, 0, 140001, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛であざとくラヴを奪う超天才びしょーじょ。\n毒と火傷で弱らせた敵をあざ笑うかのように、自分と\n先頭の味方へＴＰ回復や行動不能無効を付与し強化する。", 0, "2026/08/15 11:59:59", 0, "2026/07/31 12:00:00", 54, 2.09, "フブキ（サマー）", 140101, 54, 140101, "ふぶき", 140101, 376, 0, 140101, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】中衛でけんぞくとラヴを集めるつよつよ吸血姫。\nスキルでＴＰを吸収し、【チャームスローブ】を消費して\n放つＵＢは、ほとばしるカワいさで敵を骨抜きにする。", 0, "2030/12/31 15:00:00", 0, "2026/08/15 12:00:00", 43, 2.09, "ヴァンピィ（サマー）", 140201, 43, 140201, "うぁんぴぃ", 140201, 582, 0, 140201, 3, 0, 0, 2, 0, 450, 0);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛から、中立で平等とうそぶく認識の修正者。\n敵の認識を乱して弱体効果を付与し、一方で味方が受ける\n混乱、誘惑状態を無効化しお気に入りの彼に肩入れする。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 2.09, "ティア", 140301, 0, 140301, "てぃあ", 140301, 744, 0, 140301, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】後衛で、答えを求め彷徨うダークエルフの咎人。\nＵＢで放つ矢の呪いは二度重なれば呪詛、三度重なれば\n強烈な割合ダメージとなり、立ちはだかる敵を殺める。", 0, "2026/09/22 11:59:59", 0, "2026/09/10 12:00:00", 0, 2.09, "リーザ", 140401, 0, 140401, "りーざ", 140401, 780, 0, 140401, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛で、愛する者たちのため本意気を放つ妹竜。\n【決意の流星】を溜め覚醒すると、攻撃スキルが再発動し\nさらに味方の火力を引き上げ、渦炎で敵を灰燼に変える。", 0, "2026/09/10 11:59:59", 0, "2026/08/31 12:00:00", 0, 2.09, "ヴルム（ヴァルムドラッヘ）", 140501, 0, 140501, "うるむ", 140501, 396, 0, 140501, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛から必殺クローで敵全体を圧潰するロボ娘。\n自分へのバフと敵へのデバフで【水陸可変ブースター】が\n起動し、高頻度のＵＢでダメージの大渦潮を巻き起こす！", 0, "2030/12/31 15:00:00", 0, "2026/09/22 12:00:00", 0, 2.09, "クローチェ（サブマリン）", 140601, 0, 140601, "くろーちぇ", 140601, 400, 0, 140601, 3, 0, 0, 1, 0, 450, 0);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛で、敵影に照準を定める戦場のサレンママ。\n７種以上の弱体効果があれば更に効果が増すスキルで敵の\n装甲に風穴を開け、臨機応変の戦術で窮地を逆手に取る。", 0, "2026/10/09 11:59:59", 0, "2026/09/30 12:00:00", 0, 2.09, "サレン（ガンナー）", 140701, 0, 140701, "されん", 140701, 431, 0, 140701, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】中衛で、まばゆい弾丸の雨を降らす銃装の妖精。\n一定回数ダメージを与えるたび割合ダメージを発生させ、\n【ペタロ】で敵からの攻撃をひらりと躱し、無効化する。", 0, "2026/10/23 11:59:59", 0, "2026/10/09 12:00:00", 0, 2.09, "アメス（ガンナー）", 140801, 0, 140801, "あめす", 140801, 512, 0, 140801, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で働いて働いて働く仕事中毒な光の大精霊。\n自分に展開されているバリアに応じて性能が強化される\nスキルを武器に、ブラックな環境さえ輝く笑顔で照らす。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 2.09, "アグライア", 140901, 0, 140901, "あぐらいあ", 140901, 780, 0, 140901, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 1, "【物理】中衛から破天荒に翻弄するゴルシちゃんだぜ☆\n後ろでコソコソしてる敵を狙い打ち！　ラストスパートの\n追込でダメージレースをぶっちぎってやんよオラァッ！", 0, "2030/12/31 15:00:00", 1, "2026/10/31 12:00:00", 0, 2.09, "ゴールドシップ", 141001, 0, 141001, "ごーるどしっぷ", 141001, 368, 0, 141001, 1, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】前衛でLoAを駆ける超×９負けず嫌いなウマ娘。\n自分より攻撃力の高い味方がいると、【スタミナ】を消費\nしてスキルの性能を強化し、さらなる高みへと躍進する。", 0, "2026/11/30 11:59:59", 1, "2026/10/31 12:00:00", 0, 2.09, "アーモンドアイ", 141101, 0, 141101, "あーもんどあい", 141101, 261, 0, 141101, 3, 0, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で気高く咲き誇る時を待つ、忍耐のウマ娘。\nバトル後半になると内に秘めた【スタミナ】を解き放ち、\nしとやかな足取りで立ち塞がる敵を一息にかわす。", 0, "2026/11/30 11:59:59", 1, "2026/11/10 12:00:00", 0, 2.09, "ラッキーライラック", 141201, 0, 141201, "らっきーらいらっく", 141201, 737, 0, 141201, 3, 0, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "", 0, "2030/12/31 15:00:00", 0, "2015/04/01 15:00:00", 1, 0, "シズル（ニューイヤー）", 141401, 1, 0, "しずる", 0, 0, 0, 141401, 1, 0, 0, 0, 0, 0, 0);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "", 0, "2030/12/31 15:00:00", 0, "2015/04/01 15:00:00", 1, 0, "ヴァイオレット（イサナミ）", 141501, 0, 0, "うぁいおれっと", 0, 0, 0, 141501, 3, 0, 0, 0, 0, 0, 0);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "", 0, "2030/12/31 15:00:00", 0, "2015/04/01 15:00:00", 1, 0, "グレイス（バニー）", 141601, 4, 0, "ぐれいす", 0, 0, 0, 141601, 3, 0, 0, 0, 0, 0, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "", 0, "2030/12/31 15:00:00", 0, "2015/04/01 15:00:00", 1, 0, "ルイズマリー", 143001, 0, 0, "るいずまりー", 0, 0, 0, 143001, 3, 0, 0, 0, 0, 0, 0);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】前衛で、先手必勝の大技を繰り出す騎空士。\nスキルによるＴＰ回復は、ユニオンバーストの発動を早め\nバトルの序盤から敵前衛に大ダメージを与える。", 0, "2030/12/31 15:00:00", 0, "2015/04/01 15:00:00", 34, 1.965, "ジータ", 170101, 34, 105701, "じーた", 170101, 245, 0, 170101, 3, 4, 0, 1, 0, 450, 0);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】前衛で炎翼を背に敵を粉砕する、陽気な元気娘。\n戦いが続く程に自身の攻撃能力を強めるスキルを操り、\n高めた力で放つ超爆の一撃は、あらゆる敵を塵と化す。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 1.62, "ヒヨリ（プリンセス）", 180101, 0, 180101, "ひより", 180101, 199, 0, 180101, 3, 7, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛から極大魔法で敵を滅する願いの魔法士。\nＴＰを回復しつつ攻撃力を累積アップする補助スキルで\n自身の力を高め、強力な範囲攻撃を放ち敵を一掃する。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 1.92, "ユイ（プリンセス）", 180201, 0, 180201, "ゆい", 180201, 767, 0, 180201, 3, 1, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛で風刃を従え激戦を流麗に征く嵐翼の剣士。\n敵が多い程に効果が高まる自己強化スキルで、自身を奮い\n立たせ、強力な範囲攻撃スキルで一切の敵を鏖滅する。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 1.965, "レイ（プリンセス）", 180301, 0, 180301, "れい", 180301, 377, 0, 180301, 3, 7, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】前衛で、攻防共に絶大な力を誇る腹ペコ王女。\nＨＰが多い時は爆発的な攻撃力で、いかなる敵をも屠り、\nＨＰが減ると自己回復能力を得て、鉄壁の護りを見せる。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 1.965, "ペコリーヌ（プリンセス）", 180401, 0, 180401, "ぺこりーぬ", 180401, 155, 0, 180401, 3, 1, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛で、絶大な補助スキルを繰出す純白の巫女。\n味方の攻撃力とクリティカルダメージを強化しつつ、\n二つの全体回復スキルで味方を堅固に守護し勝利へ導く。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 2.14, "コッコロ（プリンセス）", 180501, 0, 180501, "こっころ", 180501, 555, 0, 180501, 3, 1, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】後衛で、極大魔法を操り敵を討つ姫装の猫娘。\n回復や補助を兼ねた各攻撃スキルを駆使し戦況を整え、\n極大威力のユニオンバーストを撃ち込み敵を燼滅する。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 1.92, "キャル（プリンセス）", 180601, 0, 180601, "きゃる", 180601, 747, 0, 180601, 3, 1, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】後衛から、真の絆の力を発揮する仲良し姉妹。\n敵の数が増えるほど威力が高まる攻撃スキルと、周りの\n味方を強化するスキルを操り、立ち塞がる敵を一掃する。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 1.75, "ハツネ＆シオリ", 180701, 0, 180701, "はつねしおり", 180701, 732, 0, 180701, 3, 1, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛で敵単体に必殺の一撃を放つ仲良しトリオ。\n３人の力を合わせて放つ攻撃は、相手の弱点に合わせて\n物理から魔法攻撃に変化し、どんな強い敵も退治する！", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 1.5, "ミソギ＆ミミ＆キョウカ", 180801, 0, 180801, "みそぎみみきょうか", 180801, 465, 0, 180801, 3, 1, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛で背を預けあう最高の好敵手で親友の二人。\n味方の物理攻撃をサポートしつつＨＰとＴＰを継続回復し\nＨＰが多いほど威力が増すＵＢで、共に勝利の道を征く。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 2.09, "アキノ＆サレン", 180901, 0, 180901, "あきのされん", 180901, 421, 0, 180901, 3, 1, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【魔法】中衛で、魔力共鳴し連撃を放つマナリアの双姫。\nステータスアップ効果を受けると増加する【友情の魔印】\nがスキルを強化し、波長を合わせた炎の魔槍で敵を討つ。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 2.09, "アン＆グレア", 181001, 0, 181001, "あんぐれあ", 181001, 577, 0, 181001, 3, 1, 0, 2, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛でお揃い衣装の、真偽を超えた仲良し姉妹。\n攻守共に味方を支えるシズルと、クリティカル時に強力な\nダメージを与えるリノ、姉妹の絆で困難を跳ね除ける！", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 1.92, "シズル＆リノ", 181101, 0, 181101, "しずるりの", 181101, 551, 0, 181101, 3, 1, 0, 1, 0, 450, 1);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "【物理】中衛で新たな力と共に再廻する姫装の氷竜少女。\n環境効果【絶氷】でクリティカルダメージを高め、火力と\n手数を併せ持つ剣技で、再び共に歩むため道を切り開く。", 0, "2026/10/31 11:59:59", 0, "2026/10/23 12:00:00", 0, 1.92, "シェフィ（プリンセス）", 181201, 0, 181201, "しぇふぃ", 181201, 368, 0, 181201, 3, 1, 0, 1, 0, 450, 1);
