INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, "残されたわずかな時間で宿題を終わらせんとする\nルーセント学院の生徒。楽しい夏休みの思い出を\n守るため、山積みの宿題へと立ち向かう。", 0, "2030/12/31 15:00:00", 0, "2015/04/01 15:00:00", 0, 0, "主人公", 191501, 0, 100101, "しゅじんこう", 100101, 1600, 0, 191501, 0, 0, 0, 0, 0, 150, 0);
